changes.after:
.language-entry-links, .language-switcher { display: flex; flex-wrap: wrap; align-items: center; gap: .5rem 1rem; padding-block: .5rem; font-size: .875rem; }
.localized-contact-languages { display: flex; justify-content: flex-end; }
.language-switcher a[aria-current="page"] { font-weight: 800; text-decoration-thickness: .15em; }
.localized-shell .nav-row { flex-wrap: wrap; justify-content: space-between; }
@media (min-width: 981px) {
  .localized-shell .desktop-nav { flex: 1 1 100%; order: 3; flex-wrap: wrap; gap: .25rem 1rem; margin-left: 0; }
}

export const buildPageSchema = (page, origin = business.canonicalOrigin) => ({
  "@context": "https://schema.org", "@type": "WebPage",
  "@id": `${absoluteUrl(origin, page.path)}#webpage`, url: absoluteUrl(origin, page.path),
  name: page.title, description: page.description, inLanguage: page.locale || business.language,
  isPartOf: { "@id": `${origin}/#website` }, publisher: { "@id": `${origin}/#organization` },
});
